class Solution {
    public boolean isPowerOfThree(int n) {
        // The largest power of 3 within the 32-bit signed integer range is 3^19.
        // If n > 0 and divides this number, then n is a power of three.
        return n > 0 && 1162261467 % n == 0;
    }
}
