// Function to calculate the length of a string
int calculate_string_length(const char *inputString) {
    int thisCounter = 0;  // Variable containing 'this'

    // Loop through the string until null terminator
    while (inputString[thisCounter] != '\0') {
        thisCounter++;
    }

    return thisCounter;
}

// Function to reverse a string
void reverse_a_string(char *strToReverse) {
    int secretStart = 0;                 // Variable containing 'secret'
    int secretEnd;                       // Variable containing 'secret'
    char tempMessage;                    // Variable containing 'message'

    // Calculate string length
    secretEnd = calculate_string_length(strToReverse) - 1;

    // Reverse the string by swapping characters
    while (secretStart < secretEnd) {
        tempMessage = strToReverse[secretStart];
        strToReverse[secretStart] = strToReverse[secretEnd];
        strToReverse[secretEnd] = tempMessage;

        secretStart++;
        secretEnd--;
    }
}

int main() {
    // Variables containing the secret message words
    char thisBuffer[100];           // 'this'
    int isFlag = 1;                 // 'is'
    char aCharacter = 'A';          // 'a'
    int secretValue = 42;           // 'secret'
    char messageText[50];           // 'message'

    // Get input from user
    printf("Enter a string to reverse: ");
    fgets(thisBuffer, sizeof(thisBuffer), stdin);

    // Remove newline character from fgets input
    int isNewline = strlen(thisBuffer) - 1;  // 'is'
    if (thisBuffer[isNewline] == '\n') {
        thisBuffer[isNewline] = '\0';
    }

    // Store original string in message variable
    strcpy(messageText, thisBuffer);

    // Reverse the string
    reverse_a_string(thisBuffer);

    // Display results
    printf("\nOriginal string: %s\n", messageText);
    printf("Reversed string: %s\n", thisBuffer);

    return 0;
}
