 * Sorts an array of integers in ascending order
 * 
 * Time Complexity:
 *   Best Case: O(n) - when array is already sorted
 *   Average/Worst Case: O(n²)
 * Space Complexity: O(1) - in-place sorting
 */

/**
 * Sorts an array of integers using the Bubble Sort algorithm
 * @param {Array<number>} arr - Array of integers to sort
 * @returns {Array<number>} - Sorted array in ascending order
 * @throws {Error} - If input validation fails
 */
function bubbleSort(arr) {
    // ---------- Input Validation ----------
    validateInput(arr);

    // If array has 0 or 1 element, it's already sorted
    if (arr.length <= 1) {
        console.log("Array has 0 or 1 element, already sorted.");
        return arr;
    }

    // ---------- Bubble Sort Algorithm ----------
    let n = arr.length;
    let swapped;

    console.log(`Starting Bubble Sort on array of ${n} elements`);

    // Outer loop: controls number of passes through the array
    for (let i = 0; i < n - 1; i++) {
        swapped = false;

        // Inner loop: performs comparisons and swaps adjacent elements
        // After each pass, the largest element "bubbles up" to its correct position
        for (let j = 0; j < n - i - 1; j++) {
            // Compare adjacent elements
            if (arr[j] > arr[j + 1]) {
                // Swap if they're in the wrong order
                [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
                swapped = true;
            }
        }

        // Optimization: If no swaps occurred in this pass, array is sorted
        if (!swapped) {
            console.log(`Early termination at pass ${i + 1}, array is sorted.`);
            break;
        }
    }

    console.log("Sorting completed successfully.");
    return arr;
}

/**
 * Validates input array according to requirements
 * @param {Array<number>} arr - Array to validate
 * @throws {Error} - With descriptive message if validation fails
 */
function validateInput(arr) {
    // Check if input is provided
    if (arr === undefined || arr === null) {
        throw new Error("Input array is required and cannot be null/undefined");
    }

    // Check if input is an array
    if (!Array.isArray(arr)) {
        throw new Error("Input must be an array");
    }

    // Check array length limit
    const MAX_LENGTH = 100;
    if (arr.length > MAX_LENGTH) {
        throw new Error(`Array length exceeds maximum of ${MAX_LENGTH} elements`);
    }

    // Check each element
    const MIN_VALUE = -10000;
    const MAX_VALUE = 10000;

    for (let i = 0; i < arr.length; i++) {
        const value = arr[i];

        // Check if element is a number
        if (typeof value !== 'number') {
            throw new Error(`Element at index ${i} is not a number: ${value}`);
        }

        // Check if element is an integer
        if (!Number.isInteger(value)) {
            throw new Error(`Element at index ${i} is not an integer: ${value}`);
        }

        // Check value range
        if (value < MIN_VALUE || value > MAX_VALUE) {
            throw new Error(
                `Element at index ${i} is out of range. ` +
                `Value ${value} must be between ${MIN_VALUE} and ${MAX_VALUE}`
            );
        }
    }
}

/**
 * Helper function to test the bubble sort implementation
 * @param {Array<number>} testArray - Array to test
 * @param {string} testName - Name of the test case
 */
function runTest(testArray, testName) {
    console.log(`\n=== ${testName} ===`);
    console.log(`Input: [${testArray.slice(0, 10).join(', ')}${testArray.length > 10 ? '...' : ''}]`);

    try {
        const sortedArray = bubbleSort([...testArray]); // Use copy to preserve original
        console.log(`Sorted: [${sortedArray.slice(0, 10).join(', ')}${sortedArray.length > 10 ? '...' : ''}]`);

        // Verify sort is correct
        const isSorted = sortedArray.every((val, idx, arr) => 
            idx === 0 || arr[idx - 1] <= val
        );
        console.log(`Verification: ${isSorted ? '✓ Correctly sorted' : '✗ Sorting failed'}`);
    } catch (error) {
        console.log(`Error: ${error.message}`);
    }
}

// ---------- Test Cases ----------
console.log("=== Bubble Sort Algorithm Tests ===\n");

// Test 1: Normal array
runTest([64, 34, 25, 12, 22, 11, 90], "Normal Case");

// Test 2: Already sorted array
runTest([1, 2, 3, 4, 5], "Already Sorted (Best Case)");

// Test 3: Reverse sorted array
runTest([5, 4, 3, 2, 1], "Reverse Sorted (Worst Case)");

// Test 4: Array with duplicates
runTest([3, 1, 4, 1, 5, 9, 2, 6, 5], "Array with Duplicates");

// Test 5: Single element
runTest([42], "Single Element");

// Test 6: Empty array
runTest([], "Empty Array");

// Test 7: Large array (but within limits)
runTest(Array.from({length: 50}, () => Math.floor(Math.random() * 20000) - 10000), "Random 50 Elements");

// Test 8: Edge case with min/max values
runTest([-10000, 0, 10000], "Min/Max Values");

// Test 9: Invalid input test (commented out - uncomment to test error handling)
/*
console.log("\n=== Error Handling Tests ===");
try {
    bubbleSort("not an array");
} catch (error) {
    console.log(`✓ Correctly caught: ${error.message}`);
}

try {
    bubbleSort(Array(101).fill(0));
} catch (error) {
    console.log(`✓ Correctly caught: ${error.message}`);
}

try {
    bubbleSort([1, 2.5, 3]);
} catch (error) {
    console.log(`✓ Correctly caught: ${error.message}`);
}

try {
    bubbleSort([1, 2, 15000]);
} catch (error) {
    console.log(`✓ Correctly caught: ${error.message}`);
}
*/

// ---------- Usage Example ----------
console.log("\n=== Usage Example ===");
const userArray = [34, 7, 23, 32, 5, 62];
console.log(`Original array: [${userArray.join(', ')}]`);

try {
    const sortedResult = bubbleSort(userArray);
    console.log(`Sorted array: [${sortedResult.join(', ')}]`);

    // Note: Original array is modified due to in-place sorting
    console.log(`Original array after sorting: [${userArray.join(', ')}]`);
} catch (error) {
    console.error(`Sorting failed: ${error.message}`);
}

// Export the function for use in other modules (if using Node.js/ES6 modules)
if (typeof module !== 'undefined' && module.exports) {
    module.exports = { bubbleSort, validateInput };
}
```

## Key Features of this Implementation:

1. **Algorithm Details**:
   - Implements the standard Bubble Sort algorithm
   - Includes early termination optimization (stops if no swaps occur)
   - Uses array destructuring for clean swap operations

2. **Input Validation**:
   - Checks for null/undefined input
   - Validates array type and length (≤100 elements)
   - Ensures all elements are integers within -10,000 to 10,000 range

3. **Error Handling**:
   - Descriptive error messages for different failure cases
   - Graceful handling of edge cases

4. **Complexity Analysis**:
   - Time: O(n²) average/worst case, O(n) best case
   - Space: O(1) in-place sorting

5. **Testing**:
   - Multiple test cases covering various scenarios
   - Verification of sort correctness
   - Error handling tests (commented out)

6. **Documentation**:
   - Comprehensive comments explaining logic
   - Clear function documentation
   - Console logging for visibility

The code is production-ready with proper validation and can be easily integrated into larger projects or used as a standalone sorting utility.

