    <script>
        // Artifact data
        const artifacts = [
            {
                id: 1,
                name: "Roman Terracotta Oil Lamp",
                category: "pottery",
                period: "Roman Imperial",
                date: "2nd Century CE",
                material: "Terracotta",
                site: "Pompeii, Italy",
                condition: "Good",
                description: "A well-preserved terracotta oil lamp with decorative relief showing a gladiatorial scene. Used for indoor lighting in Roman households.",
                context: "Found in the peristyle garden of the House of the Vettii, buried under volcanic ash from the eruption of Mount Vesuvius in 79 CE.",
                grid: "G7-H8",
                images: ["terracotta_lamp.jpg", "lamp_detail.jpg", "lamp_context.jpg"]
            },
            {
                id: 2,
                name: "Bronze Celtic Torc",
                category: "jewelry",
                period: "Late Iron Age",
                date: "1st Century BCE",
                material: "Bronze",
                site: "Snettisham, England",
                condition: "Excellent",
                description: "A twisted bronze neck torc with intricate terminal designs. Worn as a symbol of status and wealth among Celtic elites.",
                context: "Discovered in a hoard with other precious metal objects, likely buried as a votive offering or for safekeeping.",
                grid: "A12-B13",
                images: ["celtic_torc.jpg", "torc_detail.jpg", "torc_hoard.jpg"]
