                grid: "D4-E5",
                images: ["flint_arrowhead.jpg", "arrowhead_detail.jpg", "excavation_site.jpg"]
            },
            {
                id: 4,
                name: "Byzantine Gold Coin",
                category: "coins",
                period: "Byzantine",
                date: "6th Century CE",
                material: "Gold",
                site: "Constantinople, Turkey",
                condition: "Very Good",
                description: "A solidus coin minted under Emperor Justinian I, featuring the emperor's profile and Christian symbols.",
                context: "Found in a merchant's quarter, possibly lost during daily commercial transactions.",
                grid: "F9-G10",
                images: ["byzantine_coin.jpg", "coin_reverse.jpg", "coin_context.jpg"]
            },
            {
                id: 5,
                name: "Egyptian Faience Shabti",
                category: "pottery",
                period: "Late Period",
                date: "664-332 BCE",
                material: "Faience",
                site: "Saqqara, Egypt",
                condition: "Excellent",
                description: "A blue-glazed faience funerary figurine intended to serve the deceased in the afterlife. Inscribed with hieroglyphs.",
                context: "Excavated from a shaft tomb in the necropolis, placed alongside other burial goods.",
                grid: "M15-N16",
                images: ["shabti_figurine.jpg", "shabti_detail.jpg", "tomb_context.jpg"]
            },
            {
                id: 6,
                name: "Viking Age Bone Comb",
                category: "tools",
                period: "Viking Age",
                date: "9th-10th Century CE",
                material: "Bone",
                site: "Birka, Sweden",
                condition: "Fair",
                description: "A decorative bone comb with geometric patterns, used for personal grooming. Shows evidence of extensive use.",
                context: "Found in a workshop area, suggesting it may have been produced for trade or local use.",
                grid: "K8-L9",
                images: ["bone_comb.jpg", "comb_detail.jpg", "workshop_area.jpg"]
            }
        ];

        // DOM elements
        const homepage = document.getElementById('homepage');
        const artifactPage = document.getElementById('artifact-page');
        const homeLink = document.getElementById('home-link');
        const catalogLink = document.getElementById('catalog-link');
        const backBtn = document.getElementById('back-btn');
        const searchBtn = document.getElementById('search-btn');
        const searchInput = document.getElementById('search-input');
        const artifactGrid = document.getElementById('artifact-grid');
        const filters = document.querySelectorAll('.filter');

        // Artifact page elements
        const artifactTitle = document.getElementById('artifact-title');
        const detailName = document.getElementById('detail-name');
        const detailDescription = document.getElementById('detail-description');
        const detailId = document.getElementById('detail-id');
        const detailPeriod = document.getElementById('detail-period');
        const detailMaterial = document.getElementById('detail-material');
        const detailDate = document.getElementById('detail-date');
        const detailSite = document.getElementById('detail-site');
        const detailCondition = document.getElementById('detail-condition');
        const detailContext = document.getElementById('detail-context');
        const detailGrid = document.getElementById('detail-grid');
        const mainArtifactImg = document.getElementById('main-artifact-img');
        const thumbnailGallery = document.querySelector('.thumbnail-gallery');
        const prevBtn = document.getElementById('prev-btn');
        const nextBtn = document.getElementById('next-btn');

        // Current state
        let currentFilter = 'all';
        let currentArtifactIndex = 0;
        let filteredArtifacts = [...artifacts];

        // Initialize the homepage
        function initializeHomepage() {
            renderArtifactCards(artifacts);
            setupFilters();
        }

        // Render artifact cards on homepage
        function renderArtifactCards(artifactsToRender) {
            artifactGrid.innerHTML = '';

            artifactsToRender.forEach(artifact => {
                const card = document.createElement('div');
                card.className = 'artifact-card';
                card.dataset.id = artifact.id;

                // Use placeholder images based on category
                const imageName = artifact.images[0];

                card.innerHTML = `
                    <div class="artifact-image">
                        <img src="https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=500&q=80" alt="${artifact.name}">
                    </div>
                    <div class="artifact-info">
                        <h3>${artifact.name}</h3>
                        <div class="artifact-meta">
                            <span>${artifact.period}</span>
                            <span>${artifact.site}</span>
                        </div>
                        <p class="artifact-desc">${artifact.description}</p>
                        <a href="#" class="view-btn" data-id="${artifact.id}">View Details</a>
                    </div>
                `;

                artifactGrid.appendChild(card);
            });

            // Add event listeners to view buttons
            document.querySelectorAll('.view-btn').forEach(btn => {
                btn.addEventListener('click', function(e) {
                    e.preventDefault();
                    const artifactId = parseInt(this.dataset.id);
                    showArtifactDetail(artifactId);
                });
            });
        }

        // Setup filter functionality
        function setupFilters() {
            filters.forEach(filter => {
                filter.addEventListener('click', function() {
                    // Update active filter
                    filters.forEach(f => f.classList.remove('active'));
                    this.classList.add('active');

                    currentFilter = this.dataset.filter;

                    // Filter artifacts
                    if (currentFilter === 'all') {
                        filteredArtifacts = [...artifacts];
                    } else {
                        filteredArtifacts = artifacts.filter(artifact => 
                            artifact.category === currentFilter
                        );
                    }

                    renderArtifactCards(filteredArtifacts);
                });
            });
        }

        // Show artifact detail page
        function showArtifactDetail(artifactId) {
            const artifact = artifacts.find(a => a.id === artifactId);
            if (!artifact) return;

            currentArtifactIndex = artifacts.findIndex(a => a.id === artifactId);

            // Update artifact page content
            artifactTitle.textContent = artifact.name;
            detailName.textContent = artifact.name;
            detailDescription.textContent = artifact.description;
            detailId.textContent = `AC-2023-00${artifact.id}`;
            detailPeriod.textContent = artifact.period;
            detailMaterial.textContent = artifact.material;
            detailDate.textContent = artifact.date;
            detailSite.textContent = artifact.site;
            detailCondition.textContent = artifact.condition;
            detailContext.textContent = artifact.context;
            detailGrid.textContent = artifact.grid;

            // Set main image
            mainArtifactImg.src = "https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=500&q=80";
            mainArtifactImg.alt = artifact.name;

            // Generate thumbnails
            thumbnailGallery.innerHTML = '';
            artifact.images.forEach((image, index) => {
                const thumbnail = document.createElement('div');
                thumbnail.className = `thumbnail ${index === 0 ? 'active' : ''}`;
                thumbnail.dataset.index = index;

                // Using different Unsplash images for variety
                let imgUrl;
                if (index === 0) {
                    imgUrl = "https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=500&q=80";
                } else if (index === 1) {
                    imgUrl = "https://images.unsplash.com/photo-1545572695-789c1407474c?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=500&q=80";
                } else {
                    imgUrl = "https://images.unsplash.com/photo-1611273426858-450d8e3c9fce?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=500&q=80";
                }

                thumbnail.innerHTML = `<img src="${imgUrl}" alt="${artifact.name} detail ${index + 1}">`;

                thumbnail.addEventListener('click', function() {
                    // Update main image
                    mainArtifactImg.src = imgUrl;

                    // Update active thumbnail
                    document.querySelectorAll('.thumbnail').forEach(t => t.classList.remove('active'));
                    this.classList.add('active');
                });

                thumbnailGallery.appendChild(thumbnail);
            });

            // Show artifact page, hide homepage
            homepage.classList.add('hidden');
            artifactPage.classList.remove('hidden');

            // Update navigation active state
            document.querySelectorAll('nav a').forEach(link => link.classList.remove('active'));
        }

        // Navigation functions
        function showHomepage() {
            homepage.classList.remove('hidden');
            artifactPage.classList.add('hidden');
            homeLink.classList.add('active');
        }

        // Search functionality
        function performSearch() {
            const searchTerm = searchInput.value.toLowerCase().trim();

            if (searchTerm === '') {
                filteredArtifacts = currentFilter === 'all' ? [...artifacts] : 
                    artifacts.filter(artifact => artifact.category === currentFilter);
            } else {
                filteredArtifacts = artifacts.filter(artifact => 
                    artifact.name.toLowerCase().includes(searchTerm) ||
                    artifact.period.toLowerCase().includes(searchTerm) ||
                    artifact.material.toLowerCase().includes(searchTerm) ||
                    artifact.site.toLowerCase().includes(searchTerm) ||
                    artifact.description.toLowerCase().includes(searchTerm)
                );
            }

            renderArtifactCards(filteredArtifacts);
        }

        // Event listeners
        homeLink.addEventListener('click', function(e) {
            e.preventDefault();
            showHomepage();
            this.classList.add('active');
        });

        catalogLink.addEventListener('click', function(e) {
            e.preventDefault();
            showHomepage();
            this.classList.add('active');
            homeLink.classList.remove('active');
        });

        backBtn.addEventListener('click', function(e) {
            e.preventDefault();
            showHomepage();
        });

        searchBtn.addEventListener('click', performSearch);

        searchInput.addEventListener('keyup', function(e) {
            if (e.key === 'Enter') {
                performSearch();
            }
        });

        prevBtn.addEventListener('click', function(e) {
            e.preventDefault();
            if (currentArtifactIndex > 0) {
                currentArtifactIndex--;
            } else {
                currentArtifactIndex = artifacts.length - 1;
            }
            showArtifactDetail(artifacts[currentArtifactIndex].id);
        });

        nextBtn.addEventListener('click', function(e) {
            e.preventDefault();
            if (currentArtifactIndex < artifacts.length - 1) {
                currentArtifactIndex++;
            } else {
                currentArtifactIndex = 0;
            }
            showArtifactDetail(artifacts[currentArtifactIndex].id);
        });

        // Initialize the application
        initializeHomepage();
    </script>
</body>
</html>
